        m['a'] = 2  # overwrite, expires at 15
        fake_time[0] = 11.0
        # Access 'a' should succeed since expires_at 15 > 11
        assert m['a'] == 2
        # trigger expire of old entry
        m.expire()
        # still alive
        assert m['a'] == 2
    finally:
        calc_mod.time.monotonic = orig


