def test_memoize_basic():
    calls = []

    @memoize
    def f(x):
        calls.append(x)
        return x * 2

    assert f(3) == 6
    assert f(3) == 6
    assert calls == [3]
    assert f(4) == 8
    assert calls == [3, 4]


def test_memoize_exposes_memory():
    @memoize
    def f(x):
        return x + 1

    f(1)
    assert f.memory == {(1,): 2}


